<?php
declare(strict_types=1);
namespace QualitySystem\Controllers;
require_once dirname(__DIR__,2).'/security.php';
use PDO;use RuntimeException;use QualitySystem\Repositories\ProgramManualRepository;use QualitySystem\Services\ProgramManualService;use QualitySystem\Services\ProgramManualAutomationService;use QualitySystem\Services\ProgramManualValidationException;use QualitySystem\Security\PermissionMatrix;
final class ProgramManualController{
    private ProgramManualRepository$repo;private ProgramManualService$service;private ProgramManualAutomationService$automation;
    public function __construct(PDO$pdo,private readonly string$root){$this->repo=new ProgramManualRepository($pdo);$this->service=new ProgramManualService($pdo,$this->repo);$this->automation=new ProgramManualAutomationService($pdo,$this->repo);}
    public function dispatch(string$path,string$method):void{$role=(string)($_SESSION['role']??'');$user=(int)($_SESSION['user_id']??0);if(!PermissionMatrix::allows($role,'program_manuals','view'))$this->abort(403,'Access denied.');if($path==='/program-manuals'&&$method==='GET'){$rows=$this->repo->all($role,$user);foreach($rows as&$row)$row['readiness']=$this->repo->readiness((int)$row['id']);$this->render('program_manuals/index',compact('rows','role'));return;}if($path==='/program-manuals/create'){if(!PermissionMatrix::allows($role,'program_manuals','create'))$this->abort(403,'Access denied.');$method==='POST'?$this->save(null,$role,$user):$this->form(null,$role,$user);return;}if(preg_match('#^/program-manuals/(\d+)$#',$path,$m)&&$method==='GET'){$manual=$this->repo->find((int)$m[1],$role,$user);if(!$manual)$this->abort(404,'Program manual not found.');$this->render('program_manuals/view',['manual'=>$manual,'sections'=>$this->repo->sections((int)$m[1]),'revisions'=>$this->repo->revisions((int)$manual['program_specification_id']),'readiness'=>$this->repo->readiness((int)$m[1]),'coordination'=>$this->repo->coordination((int)$m[1]),'role'=>$role]);return;}if(preg_match('#^/program-manuals/(\d+)/compare$#',$path,$m)){if($method==='POST'){$this->reconcile((int)$m[1],$role,$user);return;}$this->compare((int)$m[1],$role,$user);return;}if(preg_match('#^/program-manuals/(\d+)/details$#',$path,$m)&&$method==='GET'){$manual=$this->repo->find((int)$m[1],$role,$user);if(!$manual)$this->abort(404,'Program manual not found.');$this->render('program_manuals/details',['manual'=>$manual,'details'=>$this->repo->detailedComparison((int)$m[1])]);return;}if(preg_match('#^/program-manuals/(\d+)/workflow$#',$path,$m)&&$method==='POST'){$this->workflow((int)$m[1],$role,$user);return;}if(preg_match('#^/program-manuals/(\d+)/archive$#',$path,$m)&&$method==='GET'){$this->archive((int)$m[1],$role,$user);return;}if(preg_match('#^/program-manuals/(\d+)/edit$#',$path,$m)){if(!PermissionMatrix::allows($role,'program_manuals','update'))$this->abort(403,'Access denied.');$method==='POST'?$this->save((int)$m[1],$role,$user):$this->form((int)$m[1],$role,$user);return;}if(preg_match('#^/program-manuals/(\d+)/download$#',$path,$m)&&$method==='GET'){$this->download((int)$m[1],$role,$user);return;}if(preg_match('#^/program-manuals/(\d+)/delete$#',$path,$m)&&$method==='POST'){try{$this->service->delete((int)$m[1],$role,$user);header('Location: /program-manuals');}catch(RuntimeException$e){$this->abort(in_array($e->getCode(),[403,404],true)?$e->getCode():500,$e->getMessage());}return;}$this->abort(404,'Not found.');}
    private function form(?int$id,string$role,int$user,array$errors=[],array$input=[]):void{$manual=$id!==null?$this->repo->find($id,$role,$user):['status'=>'Draft'];if($id!==null&&!$manual)$this->abort(404,'Program manual not found.');if($input)$manual=array_merge($manual,$input);$sections=$id!==null?$this->repo->sections($id):[];$programs=$this->repo->programs($role,$user);$revisions=$id!==null?$this->repo->revisions((int)$manual['program_specification_id']):[];$this->render('program_manuals/form',compact('manual','sections','errors','programs','revisions'));}
    private function save(?int$id,string$role,int$user):void{try{$saved=$this->service->save($_POST,$_FILES['source_pdf']??[],$role,$user,$id);header('Location: /program-manuals/'.$saved);}catch(ProgramManualValidationException$e){http_response_code(422);$this->form($id,$role,$user,$e->errors,$_POST);}catch(RuntimeException$e){$this->abort(in_array($e->getCode(),[403,404],true)?$e->getCode():500,$e->getMessage());}}
    private function download(int$id,string$role,int$user):never{$m=$this->repo->find($id,$role,$user);if(!$m||empty($m['source_storage_key']))$this->abort(404,'Manual file not found.');$path=storagePath((string)$m['source_storage_key']);if(!is_file($path)||!hash_equals((string)$m['source_sha256'],hash_file('sha256',$path)))$this->abort(404,'Manual file is unavailable or failed integrity verification.');header('Content-Type: application/pdf');header('Content-Disposition: attachment; filename="'.safeDownloadName((string)$m['source_original_name']).'"');header('Content-Length: '.filesize($path));header('X-Content-Type-Options: nosniff');readfile($path);exit;}
    private function compare(int$id,string$role,int$user,array$errors=[]):void{$manual=$this->repo->find($id,$role,$user);if(!$manual)$this->abort(404,'Program manual not found.');$this->render('program_manuals/compare',['manual'=>$manual,'comparison'=>$this->repo->comparison($id),'decisions'=>$this->repo->reconciliations($id),'errors'=>$errors,'role'=>$role]);}
    private function reconcile(int$id,string$role,int$user):void{try{$this->service->resolve($id,$_POST,$role,$user);header('Location: /program-manuals/'.$id.'/compare');}catch(ProgramManualValidationException$e){http_response_code(422);$this->compare($id,$role,$user,$e->errors);}catch(RuntimeException$e){$this->abort(in_array($e->getCode(),[403,404],true)?$e->getCode():500,$e->getMessage());}}
    private function workflow(int$id,string$role,int$user):void{try{$this->service->workflow($id,(string)($_POST['action']??''),trim((string)($_POST['note']??'')),$role,$user);header('Location: /program-manuals/'.$id);}catch(ProgramManualValidationException$e){$this->abort(422,implode(' ',$e->errors));}catch(RuntimeException$e){$this->abort(in_array($e->getCode(),[403,404,422],true)?$e->getCode():500,$e->getMessage());}}
    private function archive(int$id,string$role,int$user):never{$m=$this->repo->find($id,$role,$user);if(!$m)$this->abort(404,'Program manual not found.');$source=storagePath((string)$m['source_storage_key']);if(!is_file($source)||!hash_equals((string)$m['source_sha256'],hash_file('sha256',$source)))$this->abort(404,'Manual file failed integrity verification.');$tmp=tempnam(sys_get_temp_dir(),'manual-');$zip=new \ZipArchive();$zip->open($tmp,\ZipArchive::OVERWRITE);$zip->addFile($source,safeDownloadName((string)$m['source_original_name']));$zip->addFromString('metadata.json',json_encode(['manual'=>$m,'sections'=>$this->repo->sections($id),'plos'=>$this->repo->plos($id),'courses'=>$this->repo->courses($id),'reconciliations'=>$this->repo->reconciliations($id),'readiness'=>$this->repo->readiness($id),'coordination'=>$this->repo->coordination($id)],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));$zip->close();header('Content-Type: application/zip');header('Content-Disposition: attachment; filename="program-manual-'.$id.'-archive.zip"');header('Content-Length: '.filesize($tmp));readfile($tmp);unlink($tmp);exit;}
    private function render(string$t,array$d):void{extract($d,EXTR_SKIP);require$this->root.'/templates/'.$t.'.php';}private function abort(int$s,string$m):never{http_response_code($s);exit(htmlspecialchars($m,ENT_QUOTES,'UTF-8'));}
}
